from rules import solve_versions


def solve(data):
    return solve_versions(data)

def solve_versions(data):
    packages = data['packages']
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    names = sorted(packages)
    best_vector = None
    best_versions = None

    def is_acyclic(assigned):
        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True

            state[name] = 1
            for dependency in assigned[name].get('deps', []):
                feature = dependency.get('feature')
                if feature and feature not in features:
                    continue
                dep_name = dependency['name']
                if dep_name not in assigned or not visit(dep_name):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in assigned)

    def search(assigned, constraints):
        nonlocal best_vector, best_versions

        for name, (minimum, maximum) in constraints.items():
            if minimum > maximum:
                return
            if name in assigned:
                version = assigned[name]['version']
                if not minimum <= version <= maximum:
                    return

        unresolved = [name for name in constraints if name not in assigned]
        if not unresolved:
            if not is_acyclic(assigned):
                return
            vector = tuple(
                assigned[name]['version'] if name in assigned else -1
                for name in names
            )
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = {
                    name: assigned[name]['version']
                    for name in sorted(assigned)
                }
            return

        name = min(unresolved)
        if name not in packages:
            return

        minimum, maximum = constraints[name]
        forbidden = blocked.get(name, ())
        for row in packages[name]:
            version = row['version']
            if version in forbidden or not minimum <= version <= maximum:
                continue
            if name in pins and version != pins[name]:
                continue

            next_constraints = dict(constraints)
            valid = True
            for dependency in row.get('deps', []):
                feature = dependency.get('feature')
                if feature and feature not in features:
                    continue

                dep_name = dependency['name']
                dep_min = dependency['min']
                dep_max = dependency['max']
                if dep_name in next_constraints:
                    old_min, old_max = next_constraints[dep_name]
                    next_constraints[dep_name] = (
                        max(old_min, dep_min), min(old_max, dep_max)
                    )
                else:
                    next_constraints[dep_name] = (dep_min, dep_max)
                if next_constraints[dep_name][0] > next_constraints[dep_name][1]:
                    valid = False
                    break

            if valid:
                search({**assigned, name: row}, next_constraints)

    initial_constraints = {
        name: (bounds[0], bounds[1])
        for name, bounds in roots.items()
    }
    search({}, initial_constraints)

    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}
